"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useAuth } from "@/components/auth-context"
import { Shield, Activity, Lock, AlertTriangle, Eye, Server, Home, ShieldAlert } from "lucide-react"
import { Button } from "@/components/ui/button"
import Link from "next/link"
import dynamic from 'next/dynamic'
import { LiveFeed } from "@/components/realtime-guard/live-feed"
import { AuditLog } from "@/components/realtime-guard/audit-log"

// Load MapView dynamically to avoid SSR issues
const MapView = dynamic(() => import('@/components/realtime-guard/map-view'), { ssr: false });

export default function RealtimeGuardPage() {
    const [transactions, setTransactions] = useState<any[]>([])
    const [selectedTransaction, setSelectedTransaction] = useState<any>(null)
    const [isAuditLogOpen, setIsAuditLogOpen] = useState(false)
    const [isConnected, setIsConnected] = useState(false)

    useEffect(() => {
        const wsUrl = 'ws://localhost:4000';
        const ws = new WebSocket(wsUrl);

        ws.onopen = () => {
            console.log('Connected to WebSocket');
            setIsConnected(true);
        };

        ws.onmessage = (event) => {
            try {
                const message = JSON.parse(event.data);
                if (message.type === 'HISTORY') {
                    setTransactions(message.data);
                } else if (message.type === 'TX') {
                    setTransactions(prev => [message.data, ...prev].slice(0, 50));
                }
            } catch (e) {
                console.error('Error parsing WS message:', e);
            }
        };

        ws.onclose = () => {
            console.log('Disconnected from WebSocket');
            setIsConnected(false);
        };

        return () => ws.close();
    }, []);

    const fraudCount = transactions.filter(t => t.fraud_score > 80).length;

    return (
        <div className="min-h-screen bg-black text-green-500 font-mono flex flex-col relative overflow-hidden">
            <AuditLog isOpen={isAuditLogOpen} onClose={() => setIsAuditLogOpen(false)} />

            {/* Background Grid */}
            <div className="absolute inset-0 bg-[linear-gradient(rgba(0,255,0,0.03)_1px,transparent_1px),linear-gradient(90deg,rgba(0,255,0,0.03)_1px,transparent_1px)] bg-[size:20px_20px]" />

            <header className="border-b border-green-900/50 bg-black/80 backdrop-blur-md sticky top-0 z-50">
                <div className="container flex h-16 items-center justify-between px-4 md:px-6">
                    <div className="flex items-center gap-2">
                        <Shield className="h-6 w-6 animate-pulse" />
                        <span className="font-bold text-lg tracking-widest uppercase">RealtimeGuard <span className="text-xs bg-green-900 text-green-100 px-1 rounded">BETA</span></span>
                    </div>
                    <div className="flex items-center gap-4">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setIsAuditLogOpen(true)}
                            className="bg-green-900/20 border-green-700 text-green-400 hover:bg-green-900/40"
                        >
                            <ShieldAlert className="h-4 w-4 mr-2" />
                            Audit Log
                        </Button>
                        <div className="flex items-center gap-2 text-xs text-green-700">
                            <div className={`w-2 h-2 rounded-full ${isConnected ? 'bg-green-500 animate-ping' : 'bg-red-500'}`} />
                            {isConnected ? 'LIVE FEED ACTIVE' : 'RECONNECTING...'}
                        </div>
                        <Button variant="ghost" size="sm" asChild className="gap-2 text-green-500 hover:text-green-400 hover:bg-green-900/20">
                            <Link href="/">
                                <Home className="h-4 w-4" />
                                Home
                            </Link>
                        </Button>
                    </div>
                </div>
            </header>

            <main className="flex-1 container px-4 md:px-6 py-8 space-y-8 relative z-10">
                <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
                    <div className="bg-black/50 border border-green-900 p-4 rounded-lg">
                        <div className="flex items-center justify-between mb-2">
                            <h3 className="text-sm uppercase text-green-700">Threat Level</h3>
                            <AlertTriangle className={`h-4 w-4 ${fraudCount > 5 ? 'text-red-500' : 'text-yellow-500'}`} />
                        </div>
                        <div className={`text-2xl font-bold ${fraudCount > 5 ? 'text-red-500' : 'text-yellow-500'}`}>
                            {fraudCount > 10 ? 'CRITICAL' : fraudCount > 5 ? 'HIGH' : 'MODERATE'}
                        </div>
                    </div>
                    <div className="bg-black/50 border border-green-900 p-4 rounded-lg">
                        <div className="flex items-center justify-between mb-2">
                            <h3 className="text-sm uppercase text-green-700">Scan Frequency</h3>
                            <Activity className="h-4 w-4" />
                        </div>
                        <div className="text-2xl font-bold">{isConnected ? '2.4 GHz' : 'OFFLINE'}</div>
                    </div>
                    <div className="bg-black/50 border border-green-900 p-4 rounded-lg">
                        <div className="flex items-center justify-between mb-2">
                            <h3 className="text-sm uppercase text-green-700">Frauds Detected</h3>
                            <Shield className="h-4 w-4" />
                        </div>
                        <div className="text-2xl font-bold text-red-500">{fraudCount}</div>
                    </div>
                    <div className="bg-black/50 border border-green-900 p-4 rounded-lg">
                        <div className="flex items-center justify-between mb-2">
                            <h3 className="text-sm uppercase text-green-700">WebSocket Ping</h3>
                            <Server className="h-4 w-4" />
                        </div>
                        <div className="text-2xl font-bold">24ms</div>
                    </div>
                </div>

                <div className="grid gap-6 md:grid-cols-4 h-[600px]">
                    <div className="md:col-span-3 bg-black/50 border border-green-900 rounded-lg overflow-hidden group">
                        <MapView transactions={transactions} />
                    </div>
                    <div className="bg-black/50 border border-green-900 rounded-lg flex flex-col">
                        <div className="p-4 border-b border-green-900/50">
                            <h3 className="text-sm font-bold flex items-center gap-2">
                                <Lock className="h-4 w-4" />
                                Live Stream
                            </h3>
                        </div>
                        <LiveFeed transactions={transactions} onSelect={setSelectedTransaction} />
                    </div>
                </div>
            </main>
        </div>
    )
}

