"use client";

import React from 'react';

interface Transaction {
    id: string;
    merchant: string;
    amount: number;
    fraud_score: number;
    timestamp: string;
}

interface LiveFeedProps {
    transactions: Transaction[];
    onSelect: (tx: Transaction) => void;
}

export function LiveFeed({ transactions, onSelect }: LiveFeedProps) {
    return (
        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
            {transactions.map((tx) => (
                <div
                    key={tx.id}
                    onClick={() => onSelect(tx)}
                    className="p-3 bg-slate-950/40 rounded-lg border border-slate-800/50 hover:bg-slate-900/60 hover:border-indigo-500/30 transition-all cursor-pointer group"
                >
                    <div className="flex justify-between items-start mb-1">
                        <span className="text-[10px] font-mono text-slate-500 group-hover:text-indigo-400 transition-colors">
                            {tx.id.slice(0, 12)}...
                        </span>
                        <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${tx.fraud_score > 80 ? 'bg-red-500/10 text-red-400' : 'bg-emerald-500/10 text-emerald-400'}`}>
                            {tx.fraud_score}% RISK
                        </span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-200">{tx.merchant}</span>
                        <span className="text-xs font-mono text-slate-300">₹{tx.amount.toFixed(2)}</span>
                    </div>
                </div>
            ))}
        </div>
    );
}
